<script>
    const state = { mode: 'READ', receivedMsgs: [], currentMsgIndex: 0, drafts: [], currentDraftIndex: -1, tempInput: "" };
    function init() {
        const rawReceivedData = document.getElementById('raw-data-container').textContent.trim();
        if (rawReceivedData) {
            state.receivedMsgs = rawReceivedData.split('###').map(s => s.trim()).filter(s => s);
        }
        if (state.receivedMsgs.length === 0) {
            state.receivedMsgs = ["文本241"];
        }
        renderScreen();
    }
    function renderScreen() {
        const modeIndicator = document.getElementById('screen-mode-indicator');
        const pageIndicator = document.getElementById('screen-page-indicator');
        const readView = document.getElementById('read-view');
        const draftListView = document.getElementById('draft-list-view');
        const writeView = document.getElementById('write-view');
        const btnLeft = document.getElementById('btn-left').querySelector('span');
        const btnCenter = document.getElementById('btn-center').querySelector('span');
        const btnRight = document.getElementById('btn-right').querySelector('span');
        readView.classList.add('hidden');
        draftListView.classList.add('hidden');
        writeView.classList.add('hidden');
        if (state.mode === 'READ') {
            modeIndicator.innerText = "READ";
            pageIndicator.innerText = `${state.receivedMsgs.length > 0 ? state.currentMsgIndex + 1 : 0}/${state.receivedMsgs.length}`;
            readView.innerText = state.receivedMsgs[state.currentMsgIndex];
            readView.classList.remove('hidden');
            btnLeft.innerText = "PREV";
            btnCenter.innerText = "REPLY";
            btnRight.innerText = "NEXT";
        } else if (state.mode === 'DRAFT_LIST') {
            modeIndicator.innerText = "OUTBOX";
            pageIndicator.innerText = `${state.drafts.length}`;
            let html = "";
            if (state.drafts.length === 0) { html = "文本242"; }
            else { state.drafts.forEach((draft, index) => { html += `<div class="draft-item" onclick="editDraft(${index})">${index + 1}. ${draft}</div>`; }); }
            draftListView.innerHTML = html;
            draftListView.classList.remove('hidden');
            btnLeft.innerText = "DEL";
            btnCenter.innerText = "NEW";
            btnRight.innerText = "SEND";
        } else if (state.mode === 'EDIT') {
            modeIndicator.innerText = "EDIT";
            pageIndicator.innerText = "";
            const input = document.getElementById('msg-input');
            input.value = state.tempInput;
            writeView.classList.remove('hidden');
            btnLeft.innerText = "CANCEL";
            btnCenter.innerText = "SAVE";
            btnRight.innerText = "SEND"; 
        }
    }
    function toggleMode() {
        if (state.mode === 'READ') {
            state.mode = 'DRAFT_LIST';
        } else {
            if (state.mode === 'EDIT' && state.tempInput.trim() !== "") {
                if (state.currentDraftIndex === -1) { state.drafts.push(state.tempInput); }
                else { state.drafts[state.currentDraftIndex] = state.tempInput; }
                state.tempInput = "";
                state.currentDraftIndex = -1;
            }
            state.mode = 'READ';
        }
        renderScreen();
    }
    function handleLeftBtn() {
        if (state.mode === 'READ') {
            if (state.receivedMsgs.length === 0) return;
            state.currentMsgIndex = (state.currentMsgIndex - 1 + state.receivedMsgs.length) % state.receivedMsgs.length;
            renderScreen();
        } else if (state.mode === 'DRAFT_LIST') {
            if (state.drafts.length > 0) {
                state.drafts.pop();
                renderScreen();
            }
        } else if (state.mode === 'EDIT') {
            state.mode = 'DRAFT_LIST';
            state.tempInput = "";
            renderScreen();
        }
    }
    function handleRightBtn() {
        if (state.mode === 'READ') {
            if (state.receivedMsgs.length === 0) return;
            state.currentMsgIndex = (state.currentMsgIndex + 1) % state.receivedMsgs.length;
            renderScreen();
        } else if (state.mode === 'DRAFT_LIST') {
            if (state.drafts.length === 0) return;
            const fullMessage = state.drafts.join('\\n');

            const command = `/send 文本243${fullMessage} | /trigger`;
            if (typeof triggerSlash === 'function') {
                triggerSlash(command);
            } else {
                console.log(`文本244 ${command}`);
            }
            state.drafts = [];
            state.mode = 'READ';
            renderScreen();
        } else if (state.mode === 'EDIT') { 
            const messageToSend = state.tempInput.trim();
            if (messageToSend) {
                const command = `/send 文本243${messageToSend} | /trigger`;
                if (typeof triggerSlash === 'function') { triggerSlash(command); }
                else { console.log(`文本244 ${command}`); }
                if (state.currentDraftIndex > -1) {
                    state.drafts.splice(state.currentDraftIndex, 1);
                }
                state.tempInput = "";
                state.currentDraftIndex = -1;
                state.mode = 'DRAFT_LIST';
                renderScreen();
            }
        }
    }
    function handleCenterBtn() {
        if (state.mode === 'READ') {
            state.mode = 'DRAFT_LIST';
            createNewDraft();
        } else if (state.mode === 'DRAFT_LIST') {
            createNewDraft();
        } else if (state.mode === 'EDIT') {
            const val = document.getElementById('msg-input').value;
            if (val.trim()) {
                if (state.currentDraftIndex === -1) {
                    state.drafts.push(val);
                } else {
                    state.drafts[state.currentDraftIndex] = val;
                }
            }
            state.tempInput = "";
            state.currentDraftIndex = -1;
            state.mode = 'DRAFT_LIST';
            renderScreen();
        }
    }
    function createNewDraft() {
        state.mode = 'EDIT';
        state.currentDraftIndex = -1;
        state.tempInput = "";
        renderScreen();
        document.getElementById('msg-input').focus();
    }
    window.editDraft = function(index) {
        state.mode = 'EDIT';
        state.currentDraftIndex = index;
        state.tempInput = state.drafts[index];
        renderScreen();
        document.getElementById('msg-input').focus();
    }
    document.getElementById('msg-input').addEventListener('input', (e) => {
        state.tempInput = e.target.value;
    });
    (function(){ init(); })();
</script>
</body>
</html>
