                    else if(sanityStage < 2 && score > 800) { sanityStage = 2; updateStatus(2); say(SCRIPTS.stage2, true); }
                    else if(sanityStage < 1 && score > 200) { sanityStage = 1; updateStatus(1); say(SCRIPTS.stage1, true); }
                    else { say(SCRIPTS['stage'+sanityStage]); }
                }
            });
        }
        function updateStatus(stage) { if(stage >= 4) document.getElementById('dialogue').classList.add('glitch-text'); }
        function onDown(e) {
            e.preventDefault(); updateMouse(e);
            initialTapX = getX(e); if(!canDrop) return;
            longPressTimer = setTimeout(() => {
                isLongPress = true; isFocusing = true;
                document.getElementById('aim-line').style.display = 'block';
                currentX = Math.max(30, Math.min(W-30, mouseX));
                document.getElementById('aim-line').style.left = currentX + 'px';
            }, 200);
        }
        function onMove(e) { e.preventDefault(); updateMouse(e); if(isLongPress && canDrop) { currentX = Math.max(30, Math.min(W-30, mouseX)); document.getElementById('aim-line').style.left = currentX + 'px'; } }
        function onUp(e) {
            e.preventDefault(); clearTimeout(longPressTimer);
            if(canDrop) { dropEye(isLongPress ? currentX : initialTapX); }
            isLongPress = false; isFocusing = false; document.getElementById('aim-line').style.display = 'none';
        }
        function updateMouse(e) {
            const rect = document.getElementById('game-base').getBoundingClientRect();
            mouseX = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
            mouseY = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;
        }
        function getX(e) {
            const rect = document.getElementById('game-base').getBoundingClientRect();
            return Math.max(30, Math.min(W-30, (e.touches ? e.touches[0].clientX : e.clientX) - rect.left));
        }
        function dropEye(x) {
            canDrop = false;
            const body = Bodies.circle(x, 60, EYES[dropType].r, { restitution:0.2, render:{opacity:0} });
            body.tier = dropType; World.add(engine.world, body);
            setTimeout(()=>{
                if(!document.getElementById('end-screen').classList.contains('visible')) {
                    checkEnd();
                    if(!document.getElementById('end-screen').classList.contains('visible')) spawnNext();
                }
            }, 1200);
        }
        function spawnNext(first=false) {
            if(!first) dropType = nextType;
            nextType = Math.floor(Math.random() * 3);
            const cvs = document.getElementById('prev-cvs'); const ctx = cvs.getContext('2d'); ctx.clearRect(0,0,40,40);
            const d = EYES[nextType];
            ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(20,20,15,0,Math.PI*2); ctx.fill();
            ctx.strokeStyle = 'rgba(200,0,0,0.4)'; ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(5,20); ctx.quadraticCurveTo(12,15,15,20); ctx.stroke();
            ctx.fillStyle = d.iris; ctx.beginPath(); ctx.arc(20,20,7,0,Math.PI*2); ctx.fill();
            ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(20,20,3,0,Math.PI*2); ctx.fill();
            canDrop = true; currentX = W/2;
            say(SCRIPTS['stage'+sanityStage]);
        }
        function checkEnd() {
            let gameOverTriggered = false;
            const bodies = Composite.allBodies(engine.world);
            for(let b of bodies) {
                 if(b.label !== 'Wall' && !b.isSleeping && Vector.magnitude(b.velocity) < 0.1 && b.position.y < 120) {
                    gameOverTriggered = true; break;
                }
            }
            if(gameOverTriggered) {
                document.getElementById('end-screen').classList.add('visible');
                document.getElementById('endReason').innerText = sanityStage >= 3 ? "文本2211" : "文本2212";
                say(SCRIPTS.end, true); canDrop = false;
            }
        }
        const PI2 = Math.PI * 2;
        initGame();
    </script>
