                row.className = 'message-row-failed';
                const icon = document.createElement('div');
                icon.className = 'error-icon';
                icon.innerText = '!';
                row.appendChild(icon);
                row.appendChild(bubble);
                chatArea.appendChild(row);
            } else {
                chatArea.appendChild(bubble);
            }
            chatArea.scrollTo({top: chatArea.scrollHeight, behavior: 'smooth'});
        }
        function addFloatingText(text) {
            const el = document.createElement('div');
            el.className = 'floating-text';
            el.textContent = text;
            const x = (Math.random() - 0.5) * 50;
            const y = (Math.random() - 0.5) * 120;
            const size = 1.6 + Math.random() * 0.8;
            el.style.transform = `translate(${x}px, ${y}px)`;
            el.style.fontSize = `${size}rem`;
            floatingLayer.appendChild(el);
            setTimeout(() => { if(floatingLayer.contains(el)) el.remove(); }, 3800);
        }

        function triggerFullScreenSequence() {
            const textContent = "文本2414";
            const lineCount = 28;
            pvLayer.innerHTML = '';
            pvLayer.className = '文本2415';
            const fragment = document.createDocumentFragment();
            for (let i = 0; i < lineCount; i++) {
                const div = document.createElement('div');
                div.className = 'pv-text-line';
                div.textContent = textContent;

                div.style.animation = `textStamp 0.4s cubic-bezier(0.1, 0.9, 0.2, 1) forwards`;
                div.style.animationDelay = `${i * 0.04}s`;
                fragment.appendChild(div);
            }
            pvLayer.appendChild(fragment);

            setTimeout(() => {
                triggerExit();
            }, 2200);
        }
        function triggerExit() {
            pvLayer.classList.add('exiting');
            const lines = document.querySelectorAll('.pv-text-line');
            lines.forEach((line, index) => {
                line.style.animationDelay = `${index * 0.01}s`;
            });
            setTimeout(() => {
                pvLayer.classList.remove('active');
                pvLayer.classList.remove('exiting');
                pvLayer.innerHTML = '';
            }, 1000);
        }
        audio.addEventListener('timeupdate', () => {
            const currentTime = audio.currentTime;
            if (audio.duration) {
                const percent = (currentTime / audio.duration) * 100;
                progressFill.style.width = `${percent}%`;
            }
            if (currentTime >= 234 && !startDecayTriggered) {
                phoneContainer.classList.add('start-decay');
                startDecayTriggered = true;
            }
            if (currentTime >= 283 && !blurTriggered) {
                 phoneContainer.classList.add('final-oblivion');
                 blurTriggered = true;
            }
            while (nextLyricIndex < lyrics.length && currentTime >= lyrics[nextLyricIndex].time) {
                const currentLyric = lyrics[nextLyricIndex];
                if (currentLyric.fullScreen) {
                    triggerFullScreenSequence();
                } else if (currentLyric.special) {
                    addFloatingText(currentLyric.jp);
                } else {
                    addLyricBubble(currentLyric);
                }
                nextLyricIndex++;
            }
        });
    </script>
</body>
</html>
